#requires -Version 5.1
# TICKSTORE CDT21 - LAUNCHER G5 V005: campanha G5 nativa do candidato V005 (missao consolidada FULL de engenharia, 22/10).
# V005 = sucessor minimo do V004 que conecta o caminho D4 da cadeia FULL (GAP-01 recibo D4 publicavel; GAP-02 recibo G5 e
# instancia passados ao wrapper selado; GAP-03 pin do launcher adaptado; GAP-04 identidade unica do ZIP sucessor; GAP-09
# manifesto de fontes fechado). O G5 congelado vincula o manifesto de codigo inteiro: o G5 do V005 exige campanha nativa propria.
# Supervisor G5 V005 (embutido, SHA fixado) = logica qualificada R1+R2+R3+R4 da linha V004, revinculada ao V005:
#   R1 arvore propria por PID + criacao; R2 digests pela vista da propria entrada (os.lstat); R3 retomada deterministica so da
#   mesma campanha (-RetomarRaiz); R4 reconciliacao COMMIT->livro-razao so por prova de proveniencia (diario e censo do Job do
#   supervisor); morte abrupta numa tentativa retomada = BLOCKED. COMMITs do V003, do V004, de outro candidato ou de outra
#   campanha sao recusados antes de qualquer efeito. Revisao de fonte do implementador V005 embutida (SHA fixado).
# Fase Q (sempre, sem criar raiz nem laboratorio): pacote, revisao, NTFS, elevacao, plano de 38 unidades, isolamento de escrita;
# raizes preexistentes registradas somente leitura; suite b2d nativa (29/29) e controle negativo; censo do Job num Job aninhado;
# identidade fisica do artefato sucessor do D4 em D:\ (somente leitura, informativa).
# Fase E (somente com Q=PASS e -AutorizoLabD): raiz e laboratorio NOVOS (ou a mesma campanha com -RetomarRaiz), 38 unidades
# congeladas (inclusive os 7 testes de regressao V005 dentro das suites do plano) e fechamento de cinco partes.
# Execute a partir de PS C:\Users\silvi> em PowerShell 5.1 (autoeleva por UAC quando necessario):
#   powershell -NoProfile -ExecutionPolicy Bypass -File "C:\Users\silvi\Downloads\RUN_CDT21_G5_V005_20261022.ps1" -AutorizoLabD
# Retomada da mesma campanha apos SAFE_STOP ou interrupcao (raiz informada pelo supervisor em RETOMADA_DA_MESMA_CAMPANHA):
#   powershell -NoProfile -ExecutionPolicy Bypass -File "C:\Users\silvi\Downloads\RUN_CDT21_G5_V005_20261022.ps1" -AutorizoLabD -RetomarRaiz "<raiz>"
# Sem -AutorizoLabD: executa somente a fase Q e para (codigo 10), sem gravar no D:.
# Pre-requisito: C:\Users\silvi\Downloads\CDT21_FINAL_PACKAGE_V005_20261022.zip
# Log sempre em pasta absoluta fixa, nova a cada execucao, independente da pasta atual:
#   C:\Users\silvi\Downloads\CDT21_G5_V005_RUNS\G5V5_<yyyyMMdd_HHmmss_fff_PID>\RUN_LOG.txt (pai) e RUN_LOG_ELEVATED.txt (filho)
# Efeitos: somente laboratorio proprio (C:\Users\silvi\AppData\Local\CDT20_R08\<raiz>, C:\Users\silvi\AppData\Local\CDT21_G5_V005,
# D:\TICKSTORE_CDT19_PRE_G06_LABS\<raiz>\WRITER_EFFECTFUL) e o log fixo do codigo congelado
# C:\Users\silvi\OneDrive\Downloads\TICKSTORE_RUNS. Nenhuma escrita em D:\Base CSV. Sem B06/B07/D4/D5/canario/FULL/producao.
# Parada segura: o supervisor informa SAFE_STOP=<raiz>\SAFE_STOP.request; crie esse arquivo para parar com selo.
# Retorno: ENVIAR_AO_OPUS_CDT21_G5_V005_<stamp>.zip vai DIRETAMENTE ao Opus; a origem recebe do Opus o fechamento consolidado.
[CmdletBinding()]
param([switch]$AutorizoLabD, [switch]$ElevatedChild, [string]$SharedLogDir = '', [int]$LauncherParentPid = 0, [string]$LauncherParentCreation = '', [string]$RetomarRaiz = '')
