function Log([string]$Line) {
    Write-Host $Line
    [IO.File]::AppendAllText($Log, $Line + "`r`n", $Utf8)
}
function ShaBytes([byte[]]$Bytes) {
    $h = [Security.Cryptography.SHA256]::Create()
    try { return [BitConverter]::ToString($h.ComputeHash($Bytes)).Replace('-', '') } finally { $h.Dispose() }
}
function Sha([string]$Path) {
    $s = [IO.File]::OpenRead($Path); $h = [Security.Cryptography.SHA256]::Create()
    try { return [BitConverter]::ToString($h.ComputeHash($s)).Replace('-', '') } finally { $h.Dispose(); $s.Dispose() }
}
function Unpack([string]$B64, [string]$Expected, [string]$Path) {
    $bytes = [Convert]::FromBase64String(($B64 -replace '\s', ''))
    if ((ShaBytes $bytes) -cne $Expected) { throw ('EMBEDDED_SHA_MISMATCH=' + $Path) }
    [IO.File]::WriteAllBytes($Path, $bytes)
    if ((Sha $Path) -cne $Expected) { throw ('EMBEDDED_READBACK_MISMATCH=' + $Path) }
    Log ('UNPACKED=' + $Path + ' SHA256=' + $Expected)
}
function CreationKey($Proc) {
    if ($null -eq $Proc.CreationDate) { return '' }
    return [string]([DateTime]$Proc.CreationDate).ToUniversalTime().Ticks
}
function ClassifyG5Processes($Snapshot, [int]$SelfPid, [bool]$IsElevatedChild, [int]$ParentPid, [string]$ParentCreation) {
    # Arvore propria = este processo e, no filho UAC, o pai que o lancou; identidade = PID + instante de criacao.
    $self = @($Snapshot | Where-Object { [int]$_.ProcessId -eq $SelfPid })
    if ($self.Count -ne 1) { throw 'OWN_TREE_SELF_NOT_FOUND' }
    $selfKey = CreationKey $self[0]
    if ($selfKey -notmatch '^[0-9]+$') { throw 'OWN_TREE_SELF_CREATION_MISSING' }
    $own = @{}
    $own[[string]$SelfPid] = $selfKey
    if ($IsElevatedChild) {
        if ($ParentPid -le 0 -or $ParentCreation -notmatch '^[0-9]+$') { throw 'OWN_TREE_PARENT_IDENTITY_MISSING' }
        if ([int]$self[0].ParentProcessId -ne $ParentPid) { throw ('OWN_TREE_PARENT_PID_MISMATCH: pai real=' + $self[0].ParentProcessId + ' informado=' + $ParentPid) }
        $parent = @($Snapshot | Where-Object { [int]$_.ProcessId -eq $ParentPid })
        if ($parent.Count -ne 1) { throw ('OWN_TREE_PARENT_NOT_ALIVE: ocorrencias=' + $parent.Count) }
        $parentKey = CreationKey $parent[0]
        if ($parentKey -cne $ParentCreation) { throw ('OWN_TREE_PARENT_CREATION_MISMATCH: real=' + $parentKey + ' informado=' + $ParentCreation) }
        if ([long]$parentKey -gt [long]$selfKey) { throw 'OWN_TREE_PARENT_NEWER_THAN_CHILD' }
        $own[[string]$ParentPid] = $parentKey
    } elseif ($ParentPid -ne 0 -or $ParentCreation) { throw 'OWN_TREE_PARENT_ARGS_WITHOUT_ELEVATED_CHILD' }
    $live = @($Snapshot | Where-Object { $_.CommandLine -and
              ($_.CommandLine.IndexOf('PRE_G06_CAMPAIGN', [StringComparison]::OrdinalIgnoreCase) -ge 0 -or
               $_.CommandLine.IndexOf('CDT21_G5_V00', [StringComparison]::OrdinalIgnoreCase) -ge 0) -and
              -not ($own.ContainsKey([string]$_.ProcessId) -and $own[[string]$_.ProcessId] -ceq (CreationKey $_)) })
    $desc = (@($own.Keys | Sort-Object) | ForEach-Object { $_ + '@' + $own[$_] }) -join ';'
    return New-Object PSObject -Property @{ Own = $desc; Live = $live }
}

$code = 2
try {
    Log ('RESULT_CONTEXT=ChatGPT | PROJECT=Base de Dados CSV / Tickstore | THREAD=' + $Thread)
    Log ('RUN_LOG=' + $Log)
    Log ('LAUNCHER=' + $PSCommandPath + ' SHA256=' + (Sha $PSCommandPath))
    Log ('MODO=G5_V005_' + $(if ($RetomarRaiz) { 'RETOMADA_MESMA_CAMPANHA' } else { 'NOVA_CAMPANHA' }) + ' FASE_Q=SEMPRE FASE_E=' + $(if ($AutorizoLabD) { 'AUTORIZADA' } else { 'NAO_AUTORIZADA' }) + $(if ($RetomarRaiz) { ' RAIZ=' + $RetomarRaiz } else { ' RAIZ=NOVA (gerada pelo supervisor)' }))
    Log 'ESCOPO=G5_TECNICO_V005; LABORATORIO_PROPRIO; PRODUCAO=NAO; COMMITS_V003=NAO_REUTILIZADOS; COMMITS_V004=NAO_REUTILIZADOS; COMMITS_DE_OUTRA_CAMPANHA=NAO_REUTILIZADOS; RETOMADA=SO_MESMA_CAMPANHA_V005; B06=NOT_STARTED; B07=NOT_STARTED; D4_D5=NOT_STARTED; CANARIO=NAO; FULL=NAO'
    if ($PSVersionTable.PSEdition -ne 'Desktop' -or $PSVersionTable.PSVersion.Major -ne 5 -or $PSVersionTable.PSVersion.Minor -ne 1) { throw 'WINDOWS_POWERSHELL_5_1_REQUIRED' }
    $ResumeArgs = @()
    if ($RetomarRaiz) {
        $rr = [IO.Path]::GetFullPath($RetomarRaiz)
        if (-not $env:LOCALAPPDATA -or [IO.Path]::GetDirectoryName($rr) -ine (Join-Path $env:LOCALAPPDATA 'CDT20_R08') -or
            [IO.Path]::GetFileName($rr) -cnotmatch '^R08_Q1_[0-9]{14}_[0-9a-f]{12}$' -or -not (Test-Path -LiteralPath $rr -PathType Container)) {
            throw ('RETOMAR_RAIZ_INVALIDA=' + $RetomarRaiz)
        }
        $RetomarRaiz = $rr
        $ResumeArgs = @('--resume-root', $rr)
        Log ('RETOMADA_SOLICITADA=' + $rr + ' (admissao decidida pela Fase Q: mesma campanha, mesmos bytes, livro-razao)')
    }
    $id = [Security.Principal.WindowsIdentity]::GetCurrent()
    $principal = New-Object Security.Principal.WindowsPrincipal($id)
    if (-not $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
        if ($ElevatedChild) { throw 'ELEVATION_REENTRY_GUARD: rights missing after RunAs' }
        $selfProc = @(Get-CimInstance Win32_Process -Filter ('ProcessId = ' + $PID) -ErrorAction Stop)
        if ($selfProc.Count -ne 1) { throw 'OWN_TREE_SELF_NOT_FOUND' }
        $selfCreation = CreationKey $selfProc[0]
        if ($selfCreation -notmatch '^[0-9]+$') { throw 'OWN_TREE_SELF_CREATION_MISSING' }
        $si = New-Object System.Diagnostics.ProcessStartInfo
        $si.FileName = Join-Path $PSHOME 'powershell.exe'
        $si.WorkingDirectory = 'C:\Users\silvi'
        $si.UseShellExecute = $true
        $si.Verb = 'runas'
        $si.Arguments = '-NoProfile -ExecutionPolicy Bypass -File "' + $PSCommandPath + '"' + $(if ($AutorizoLabD) { ' -AutorizoLabD' } else { '' }) + $(if ($RetomarRaiz) { ' -RetomarRaiz "' + $RetomarRaiz + '"' } else { '' }) + ' -ElevatedChild -SharedLogDir "' + $LogDir + '" -LauncherParentPid ' + $PID + ' -LauncherParentCreation ' + $selfCreation
        Log ('UAC_REQUEST=YES LOG_COMPARTILHADO=' + $LogDir + ' IDENTIDADE_PAI=' + $PID + '@' + $selfCreation)
        $child = [System.Diagnostics.Process]::Start($si)
        if ($null -eq $child) { throw 'UAC_NO_CHILD_PROCESS' }
        try {
            Log ('ELEVATED_CHILD_PID=' + $child.Id + ' (log do filho: ' + (Join-Path $LogDir 'RUN_LOG_ELEVATED.txt') + ')')
            $deadline = [DateTime]::UtcNow.AddHours(4); $n = 0
            while (-not $child.WaitForExit(5000)) {
                $n++; if ($n % 6 -eq 0) { Log ('ELEVATED_CHILD_ACTIVE=YES PID=' + $child.Id) }
                if ([DateTime]::UtcNow -ge $deadline) { throw 'ELEVATED_CHILD_WAIT_TIMEOUT: sem encerramento automatico; inspecione o filho e os logs' }
            }
            $child.WaitForExit(); $child.Refresh()
            $code = [int]$child.ExitCode
            Log ('ELEVATED_CHILD_EXIT_CODE=' + $code)
        } finally { $child.Dispose() }
    } else {
        if (-not $env:LOCALAPPDATA) { throw 'LOCALAPPDATA_MISSING' }
        if (-not (Test-Path -LiteralPath $Python -PathType Leaf)) { throw ('PYTHON_MISSING=' + $Python) }
        if ((Sha $Python) -cne $ExpectedPythonSha) { throw 'PYTHON_SHA_MISMATCH' }
        $Package = Join-Path $Downloads $PackageName
        if (-not (Test-Path -LiteralPath $Package -PathType Leaf)) { throw ('PACKAGE_NOT_FOUND=' + $Package) }
        $packageSha = Sha $Package
        if ($packageSha -cne $ExpectedPackageSha) { throw ('PACKAGE_SHA_MISMATCH=' + $packageSha) }
        Log ('PACKAGE=' + $Package + ' SHA256_OK=' + $packageSha)
        $snapshot = @(Get-CimInstance Win32_Process -ErrorAction Stop)
        $scan = ClassifyG5Processes $snapshot $PID $ElevatedChild.IsPresent $LauncherParentPid $LauncherParentCreation
        Log ('ARVORE_PROPRIA=' + $scan.Own)
        $live = @($scan.Live)
        foreach ($p in $live) { Log ('LIVE_PROCESS=' + $p.ProcessId + ' ' + $p.Name + ' ' + $p.CommandLine) }
        if ($live.Count -gt 0) { throw 'LIVE_G5_CAMPAIGN_PROCESS: outra campanha G5 esta ativa; aguarde o termino dela' }
        Log 'CAMPANHAS_G5_ATIVAS=0'
        $Stage = Join-Path $env:LOCALAPPDATA ('CDT21_G5_V005\STAGE_' + $Stamp)
        if (Test-Path -LiteralPath $Stage) { throw 'STAGE_EXISTS' }
        New-Item -ItemType Directory -Path (Join-Path $Stage 'TEMP') -ErrorAction Stop | Out-Null
        $Supervisor = Join-Path $Stage $SupervisorName
        $Review = Join-Path $Stage $ReviewName
        Unpack $SupervisorB64 $SupervisorSha $Supervisor
        Unpack $ReviewB64 $ReviewSha $Review
        $oldTemp = $env:TEMP; $oldTmp = $env:TMP
        $env:TEMP = Join-Path $Stage 'TEMP'; $env:TMP = $env:TEMP
        $oldPref = $ErrorActionPreference
        try {
            $ErrorActionPreference = 'Continue'
            Log 'FASE_Q=INICIO (qualificacao nativa; nao cria raiz nem laboratorio; inclui b2d nativo 2x, ~1-3 min)'
            & $Python -I -B $Supervisor --qualify-only --package $Package --review $Review --log-dir $LogDir --stage $Stage @ResumeArgs 2>&1 | ForEach-Object { Log ([string]$_) }
            $qcode = $LASTEXITCODE
            $qfile = Join-Path $LogDir 'QUALIFICATION_RESULT.json'
            if (Test-Path -LiteralPath $qfile -PathType Leaf) { Log ('COLLECTED=' + $qfile + ' SHA256=' + (Sha $qfile)) }
            if ($qcode -ne 0) { throw ('FASE_Q_NAO_PASSOU (exit ' + $qcode + '); campanha NAO iniciada; ver QUALIFICATION_RESULT.json') }
            Log 'FASE_Q=PASS_WINDOWS_QUALIFICATION'
            if (-not $AutorizoLabD) {
                Log 'FASE_E=NAO_INICIADA: sem -AutorizoLabD. A campanha grava arquivos pequenos (ordem de centenas de KB) em D:\TICKSTORE_CDT19_PRE_G06_LABS\<raiz nova>\WRITER_EFFECTFUL; ha um incidente de perda de dados no D: em diagnostico.'
                $code = 10
            } else {
                Log 'FASE_E=INICIO ETA=cerca de 15 a 25 min (38 unidades novas + fechamento; referencia nativa V003: 653 s para 33 unidades). Heartbeats abaixo.'
                & $Python -I -B $Supervisor --package $Package --review $Review --log-dir $LogDir --stage $Stage --require-qualification $qfile @ResumeArgs 2>&1 | ForEach-Object { Log ([string]$_) }
                $code = $LASTEXITCODE
                foreach ($name in @('SUPERVISOR_RESULT.json', 'CDT21_G5_V005_RETURN.zip')) {
                    $p = Join-Path $LogDir $name
                    if (Test-Path -LiteralPath $p -PathType Leaf) { Log ('COLLECTED=' + $p + ' SHA256=' + (Sha $p)) } else { Log ('NOT_PRODUCED=' + $name) }
                }
                if ($code -eq 0) { Log 'G5_TECNICO_V005=PASS_NATIVE_V005_G5_TECHNICAL_FIVE_PART; B06=NOT_STARTED' }
                else { Log 'G5_TECNICO_V005=NAO_CONCLUIDO (ver SUPERVISOR_RESULT.json); B06=NOT_STARTED' }
            }
        } finally {
            $ErrorActionPreference = $oldPref
            $env:TEMP = $oldTemp; $env:TMP = $oldTmp
        }
    }
} catch {
    Log ('G5_V005_BLOCKED=' + $_.Exception.Message)
    $code = 2
} finally {
    Log ('EXIT_CODE=' + $code)
    if ($ElevatedChild) {
        Log 'FILHO_ELEVADO_CONCLUIDO (o processo pai empacota o retorno unico)'
    } else {
        $Send = Join-Path $LogDir ('ENVIAR_AO_OPUS_CDT21_G5_V005_' + $Stamp + '.zip')
        try {
            Add-Type -AssemblyName System.IO.Compression
            Add-Type -AssemblyName System.IO.Compression.FileSystem
            $zip = [IO.Compression.ZipFile]::Open($Send, [IO.Compression.ZipArchiveMode]::Create)
            try {
                foreach ($name in @('RUN_LOG.txt', 'RUN_LOG_ELEVATED.txt', 'QUALIFICATION_RESULT.json', 'B2D_NATIVE_FIXED_LAYOUT.log',
                                'B2D_NATIVE_R1_LAYOUT.log', 'SUPERVISOR_RESULT.json', 'CDT21_G5_V005_RETURN.zip')) {
                    $p = Join-Path $LogDir $name
                    if (Test-Path -LiteralPath $p -PathType Leaf) {
                        $level = [IO.Compression.CompressionLevel]::Optimal
                        if ($name.EndsWith('.zip')) { $level = [IO.Compression.CompressionLevel]::NoCompression }
                        [void][IO.Compression.ZipFileExtensions]::CreateEntryFromFile($zip, $p, $name, $level)
                    }
                }
            } finally { $zip.Dispose() }
            Log ('ENVIE_O_RETORNO=' + $Send)
            Log ('ENVIE_O_RETORNO_SHA256=' + (Sha $Send))
        } catch {
            Log ('ENVIAR_ZIP_FALHOU=' + $_.Exception.Message + ' (envie o conteudo de ' + $LogDir + ')')
        }
        Log ('Devolva este retorno DIRETAMENTE ao Opus (Claude Code), na mesma conversa de engenharia CDT21: anexe o arquivo ENVIE_O_RETORNO acima e cole este log.')
        Log ('A origem (ChatGPT, projeto Base de Dados CSV / Tickstore, conversa ' + $Thread + ') recebe do Opus o fechamento consolidado.')
        Log ('RESULT_RETURN_TO=Opus | ORIGIN=ChatGPT | PROJECT=Base de Dados CSV / Tickstore | THREAD=' + $Thread)
    }
}
exit $code
